"use client";
/* Bumble, from the Piixpal shadcn registry. Options: https://piixpal.dvkk.dev/components/ */
import * as React from "react";
import { loadPiixpal, piixAttrs, type PiixProps } from "@/lib/piixpal";

export function Bumble(props: PiixProps) {
  React.useEffect(() => { loadPiixpal("bumble"); }, []);
  return React.createElement("piix-pal", { "pal": "bumble", ...piixAttrs(props) });
}

export default Bumble;
